# Create a release archive excluding node_modules, .git, and this script
tar --exclude="node_modules" --exclude=".git" --exclude="deploy.sh" -czf release.tar.gz .

echo "Release archive created: release.tar.gz"

# Send validated config to deployment orchestrator
echo "Sending config to deployment orchestrator..."
CONFIG_JSON=$(node -e "
  const fs = require('fs');
  const env = fs.readFileSync('.env.test', 'utf8');
  const config = {};
  env.split('\n').forEach(line => {
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, value] = line.split('=');
      config[key.trim()] = value.trim();
    }
  });
  console.log(JSON.stringify({ config }));
")

curl -s -X POST http://localhost:3003/api/deploy-config \
  -H "Content-Type: application/json" \
  -d "$CONFIG_JSON"

if [ $? -eq 0 ]; then
  echo "Config sent to deployment orchestrator successfully."
else
  echo "Failed to send config to deployment orchestrator."
  exit 1
fi

