        value = $2;
    }
    # Escape quotes and backslashes in value
    gsub(/\\/, "\\\\", value);
    gsub(/\"/, "\\\"", value);
    # Add the key-value pair to JSON
    if (NR == 1) {
        printf "{\"%s\": \"%s\"", $1, value);
    } else {
        printf ", \"%s\": \"%s\"", $1, value);
    }
} END {print "}"}')

# Check if JSON was created successfully
